DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.guard_rental_refund_basis()'::regprocedure) INTO definition; definition:=replace(definition,'IF TG_OP=''UPDATE'' AND EXISTS(SELECT 1 FROM public.rental_order_refunds WHERE basis_id=OLD.id)', 'IF TG_OP=''UPDATE'' AND (EXISTS(SELECT 1 FROM public.rental_order_refunds WHERE basis_id=OLD.id) OR EXISTS(SELECT 1 FROM public.order_refund_requests WHERE inquiry_id=OLD.inquiry_id))'); EXECUTE definition; END $$;
CREATE OR REPLACE FUNCTION public.guard_order_refund_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE totals jsonb; a jsonb; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Nicht berechtigt'; END IF; PERFORM 1 FROM public.rental_inquiries WHERE id=NEW.inquiry_id FOR UPDATE; totals:=public.order_refund_totals(NEW.inquiry_id); IF (totals->>'pending')::boolean OR NEW.deposit_cents>(totals->>'deposit_available')::bigint OR NEW.rent_cents>(totals->>'rent_available')::bigint OR totals->>'blocked_reason' IS NOT NULL THEN RAISE EXCEPTION 'Erstattungsanspruch bereits verbraucht oder gesperrt' USING ERRCODE='23514'; END IF; IF NEW.payout_method='stripe' THEN IF jsonb_typeof(NEW.allocations)<>'array' OR jsonb_array_length(NEW.allocations)=0 OR (SELECT count(*) FROM jsonb_array_elements(NEW.allocations))<>(SELECT count(DISTINCT value->>'payment_intent') FROM jsonb_array_elements(NEW.allocations)) OR coalesce((SELECT sum((value->>'deposit_cents')::bigint) FROM jsonb_array_elements(NEW.allocations)),0)<>NEW.deposit_cents OR coalesce((SELECT sum((value->>'rent_cents')::bigint) FROM jsonb_array_elements(NEW.allocations)),0)<>NEW.rent_cents THEN RAISE EXCEPTION 'Ungültige Erstattungsaufteilung'; END IF; FOR a IN SELECT value FROM jsonb_array_elements(NEW.allocations) LOOP IF (a->>'deposit_cents')::bigint<0 OR (a->>'rent_cents')::bigint<0 OR (a->>'amount_cents')::bigint<>(a->>'deposit_cents')::bigint+(a->>'rent_cents')::bigint OR a->>'status' IS DISTINCT FROM 'creating' OR a->>'refund_id' IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.offer_payment_links WHERE inquiry_id=NEW.inquiry_id AND inquiry_table='rental_inquiries' AND status='paid' AND payment_intent_id=a->>'payment_intent') THEN RAISE EXCEPTION 'Ungültige Originalzahlungszuordnung'; END IF; END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER order_refund_insert_guard BEFORE INSERT ON public.order_refund_requests FOR EACH ROW EXECUTE FUNCTION public.guard_order_refund_insert();
CREATE OR REPLACE FUNCTION public.guard_order_refund_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Erstattungsnachweis unveränderlich'; END IF; IF (to_jsonb(NEW)-'status'-'allocations'-'completed_at'-'bank_reference') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'allocations'-'completed_at'-'bank_reference') OR (OLD.status='succeeded' AND NEW.status<>'succeeded') OR (OLD.completed_at IS NOT NULL AND NEW.completed_at IS DISTINCT FROM OLD.completed_at) OR (OLD.bank_reference IS NOT NULL AND OLD.bank_reference IS DISTINCT FROM NEW.bank_reference) OR jsonb_array_length(NEW.allocations)<>jsonb_array_length(OLD.allocations) OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.allocations)n WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(OLD.allocations)o WHERE (n-'status'-'refund_id')=(o-'status'-'refund_id') AND (o->>'refund_id' IS NULL OR o->>'refund_id'=n->>'refund_id') AND (o->>'status' NOT IN ('succeeded','failed','canceled') OR o->>'status'=n->>'status'))) THEN RAISE EXCEPTION 'Erstattungsnachweis unveränderlich'; END IF; IF NEW.status='succeeded' AND NEW.payout_method='stripe' AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.allocations)a WHERE a->>'status'<>'succeeded' OR NOT EXISTS(SELECT 1 FROM public.stripe_refund_receipts p WHERE p.refund_id=a->>'refund_id' AND p.payment_intent=a->>'payment_intent' AND p.amount_cents=(a->>'amount_cents')::bigint AND p.status='succeeded')) THEN RAISE EXCEPTION 'Providerbeleg fehlt'; END IF; RETURN NEW; END $$;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.order_refund_totals(uuid)'::regprocedure) INTO definition; definition:=replace(definition,'IF b.id IS NOT NULL THEN rent_due', 'IF b.id IS NOT NULL AND invoices>0 THEN reason:=''Vorhandene Belege erfordern Korrekturabrechnung''; END IF; IF b.id IS NOT NULL THEN rent_due'); EXECUTE definition; END $$;
CREATE OR REPLACE FUNCTION public.check_rental_invoice_refunds(_inquiry uuid,_gross numeric,_paid numeric) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.deposit_settlements; b public.rental_refund_bases; r public.rental_order_refunds; due bigint; refunded bigint:=0; combined bigint:=0; deposit_combined bigint:=0; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('rental-refund-invoice:'||_inquiry::text,0)); SELECT * INTO s FROM public.deposit_settlements WHERE rental_inquiry_id=_inquiry; SELECT coalesce(sum(rent_cents),0),coalesce(sum(deposit_cents),0) INTO combined,deposit_combined FROM public.order_refund_requests WHERE inquiry_id=_inquiry AND status='succeeded'; IF EXISTS(SELECT 1 FROM public.order_refund_requests WHERE inquiry_id=_inquiry AND status IN ('creating','pending','partial_failed')) THEN RAISE EXCEPTION 'Rechnung gesperrt: Erstattung noch ungeklärt'; END IF; IF s.id IS NOT NULL AND s.balance>0 AND ((s.payout_status IS DISTINCT FROM 'paid' AND deposit_combined<round(s.balance*100)) OR (s.payout_method='stripe' AND NOT public.deposit_payout_verified(_inquiry,round(s.balance*100)::bigint) AND deposit_combined<round(s.balance*100))) THEN RAISE EXCEPTION 'Rechnung gesperrt: Kautionserstattung noch offen'; END IF; due:=greatest(0,round((_paid-_gross)*100)); SELECT * INTO b FROM public.rental_refund_bases WHERE inquiry_id=_inquiry; IF b.id IS NOT NULL THEN SELECT * INTO r FROM public.rental_order_refunds WHERE basis_id=b.id; END IF; IF due>0 OR r.id IS NOT NULL OR combined>0 THEN IF b.id IS NULL OR b.gross_amount IS DISTINCT FROM _gross OR b.paid_amount IS DISTINCT FROM _paid THEN RAISE EXCEPTION 'Rechnung gesperrt: Erstattungsgrundlage zuerst mit aktueller Vorschau prüfen'; END IF; refunded:=CASE WHEN r.status='succeeded' THEN r.amount_cents ELSE 0 END+combined; IF refunded<>due THEN RAISE EXCEPTION 'Rechnung gesperrt: Mietguthabenerstattung noch offen'; END IF; END IF; RETURN jsonb_build_object('basis_id',b.id,'refunded_cents',refunded); END $$;